/**
 * Shared screenshot-evidence naming and discovery helpers.
 *
 * The repository has two accepted filename shapes:
 *   - {slug}-{locale}.png
 *   - {slug}-{locale}-{theme}-{viewport}.png
 *
 * Keep parsing here so Terrain, Analysis, Page Health, and the institutional
 * activation validator cannot silently disagree about which files are proof.
 *
 * LATTICE:BEGIN — generated by lib/build-lattice-headers.js from docs/lattice-map.json. Do not hand-edit; edit the JSON and regenerate.
 *   role      : shared screenshot-evidence filename parser and deterministic projection helper
 *   reads     : (none)
 *   writes    : (none)
 *   loaded-by : lib/check-institutional-surfaces.js
 *               lib/build-page-health.js
 *               lib/build-terrain-map.js
 *               lib/build-analysis-index.js
 *               scripts/screenshot-institutional.js
 *               tests/36-build-analysis-index.test.js
 *   tested-by : tests/28-build-terrain-map.test.js
 *               tests/36-build-analysis-index.test.js
 *               tests/44-page-health.test.js
 *               tests/54-institutional-surfaces.test.js
 *
 *   CHANGE MAP — if you touch X here, also check:
 *     legacy or matrix filename grammar changed:
 *       - lib/check-institutional-surfaces.js (activation evidence path)
 *       - lib/build-page-health.js (locale and exact-file health evidence)
 *       - lib/build-terrain-map.js (representative screen plus exact evidence records)
 *       - lib/build-analysis-index.js (per-page evidence projection)
 *       - scripts/screenshot-institutional.js (matrix writer)
 *       - tests/28, tests/44, and tests/54
 * LATTICE:END
 */

'use strict';

const SCREENSHOT_PREFIX = 'docs/screenshots/';
const ASSET_PROJECTION_SCHEMA = 'vextreme.screenshot-evidence-assets-projection/v1';
const ASSET_MANIFEST_SCHEMA = 'vextreme-assets.screenshot-evidence/v1';

function evidenceFilename(slug, locale, theme, viewport) {
  return `${slug}-${locale}-${theme}-${viewport}.png`;
}

function parseScreenshotFilename(filename) {
  if (typeof filename !== 'string') return null;

  const matrix = filename.match(/^(.+)-([a-z]{2})-([a-z0-9]+(?:-[a-z0-9]+)*)-([1-9][0-9]*)\.png$/);
  if (matrix) {
    return {
      slug: matrix[1],
      locale: matrix[2],
      theme: matrix[3],
      viewport: Number(matrix[4]),
      kind: 'matrix',
      path: SCREENSHOT_PREFIX + filename,
    };
  }

  const legacy = filename.match(/^(.+)-([a-z]{2})\.png$/);
  if (!legacy) return null;
  return {
    slug: legacy[1],
    locale: legacy[2],
    theme: null,
    viewport: null,
    kind: 'legacy',
    path: SCREENSHOT_PREFIX + filename,
  };
}

function findScreenshotEvidence(files) {
  const bySlug = {};
  for (const filename of (files || []).slice().sort()) {
    const record = parseScreenshotFilename(filename);
    if (!record) continue;
    bySlug[record.slug] = bySlug[record.slug] || [];
    bySlug[record.slug].push(record);
  }
  return bySlug;
}

function findAssetScreenshotEvidence(projection, namespace = 'vextreme') {
  if (!projection) return {};
  if (projection.schemaVersion !== ASSET_PROJECTION_SCHEMA) {
    throw new Error('unsupported Assets screenshot projection schema: ' + String(projection.schemaVersion || '(missing)'));
  }
  const source = projection.source || {};
  if (source.manifestSchemaVersion !== ASSET_MANIFEST_SCHEMA) {
    throw new Error('unsupported Assets screenshot manifest schema: ' + String(source.manifestSchemaVersion || '(missing)'));
  }
  if (typeof source.publicOrigin !== 'string' || !/^https:\/\//.test(source.publicOrigin)) {
    throw new Error('Assets screenshot projection requires an https publicOrigin');
  }
  if (!/^[0-9a-f]{40}$/i.test(source.commit || '')) {
    throw new Error('Assets screenshot projection requires an exact source commit');
  }

  const origin = source.publicOrigin.replace(/\/$/, '');
  const bySlug = {};
  for (const key of Object.keys(projection.records || {}).sort()) {
    const record = projection.records[key];
    if (!record || record.namespace !== namespace) continue;
    if (typeof record.slug !== 'string' || !record.slug ||
        typeof record.locale !== 'string' || !record.locale ||
        typeof record.path !== 'string' || !record.path ||
        !/^[0-9a-f]{64}$/.test(record.sha256 || '')) {
      throw new Error('invalid Assets screenshot evidence record: ' + key);
    }
    if (!record.path.startsWith('evidence/screenshots/')) {
      throw new Error('Assets screenshot evidence path is outside custody namespace: ' + record.path);
    }
    const normalized = {
      slug: record.slug,
      locale: record.locale,
      theme: record.theme || null,
      viewport: Number.isInteger(record.viewport) ? record.viewport : null,
      kind: 'asset',
      storage: 'assets',
      path: origin + '/' + record.path,
      sha256: record.sha256,
      captureKind: record.captureKind || null,
      source: record.source || null,
      assetCoordinate: key,
      assetRepository: source.repository || null,
      assetCommit: source.commit,
    };
    bySlug[normalized.slug] = bySlug[normalized.slug] || [];
    bySlug[normalized.slug].push(normalized);
  }
  return bySlug;
}

function mergeScreenshotEvidence(...sources) {
  const merged = {};
  for (const source of sources) {
    for (const slug of Object.keys(source || {}).sort()) {
      merged[slug] = merged[slug] || [];
      merged[slug].push(...(source[slug] || []));
    }
  }
  return merged;
}

function isInstitutionalMatrixEvidence(record) {
  if (!record || typeof record !== 'object') return false;
  if (record.storage !== 'assets') return record.kind === 'matrix';

  const source = record.source || {};
  return record.kind === 'asset' &&
    record.captureKind === 'institutional-localization' &&
    typeof record.slug === 'string' && Boolean(record.slug) &&
    typeof record.locale === 'string' && Boolean(record.locale) &&
    typeof record.theme === 'string' && Boolean(record.theme) &&
    Number.isInteger(record.viewport) && record.viewport > 0 &&
    source.repository === 'vgong24/Vextreme' &&
    /^[0-9a-f]{40}$/i.test(source.commit || '') &&
    source.path === 'pages/' + record.slug + '.html';
}

function representativeScreenshots(evidenceBySlug) {
  const bySlug = {};
  for (const slug of Object.keys(evidenceBySlug || {}).sort()) {
    const byLocale = {};
    for (const record of evidenceBySlug[slug]) {
      byLocale[record.locale] = byLocale[record.locale] || [];
      byLocale[record.locale].push(record);
    }

    const representatives = {};
    for (const locale of Object.keys(byLocale).sort()) {
      const candidates = byLocale[locale].slice().sort((a, b) => {
        const storageRank = record => record.storage === 'assets' ? 1 : 0;
        const kindRank = record => record.kind === 'legacy' ? 0 : (record.kind === 'matrix' ? 1 : 2);
        if (storageRank(a) !== storageRank(b)) return storageRank(a) - storageRank(b);
        if (kindRank(a) !== kindRank(b)) return kindRank(a) - kindRank(b);
        if ((a.viewport || 0) !== (b.viewport || 0)) return (b.viewport || 0) - (a.viewport || 0);
        return String(a.theme || '').localeCompare(String(b.theme || '')) || a.path.localeCompare(b.path);
      });
      representatives[locale] = candidates[0].path;
    }
    bySlug[slug] = representatives;
  }
  return bySlug;
}

function findScreenshots(files) {
  return representativeScreenshots(findScreenshotEvidence(files));
}

module.exports = {
  SCREENSHOT_PREFIX,
  evidenceFilename,
  parseScreenshotFilename,
  findScreenshotEvidence,
  findAssetScreenshotEvidence,
  mergeScreenshotEvidence,
  isInstitutionalMatrixEvidence,
  representativeScreenshots,
  findScreenshots,
};

